// Extract message data from webhook payload
// Supports both SMSLeopard and Meta formats

const payload = $input.item.json;
let messageData = {};

// Handle SMSLeopard format
if (payload.message) {
  messageData = {
    from: payload.message.from,
    text: payload.message.text?.body || payload.message.body,
    type: payload.message.type || 'text',
    message_id: payload.message.id,
    timestamp: payload.message.timestamp || Math.floor(Date.now() / 1000)
  };
}
// Handle Meta format
else if (payload.entry && payload.entry[0]?.changes[0]?.value?.messages) {
  const msg = payload.entry[0].changes[0].value.messages[0];
  messageData = {
    from: msg.from,
    text: msg.text?.body,
    type: msg.type,
    message_id: msg.id,
    timestamp: msg.timestamp
  };
}

return messageData;

// Classify message type based on content
// Architecture: See docs/WAAS_ARCHITECTURE.md (Message Taxonomy)

const text = ($input.item.json.text || '').toLowerCase();
let messageType = 'unknown';

// Order keywords (English, Swahili, Sheng)
if (text.match(/order|nataka|taka|nimtaki|buy|want|nunua/i)) {
  messageType = 'order';
}
// Payment query
else if (text.match(/payment|paid|pesa|lipa|malipo/i)) {
  messageType = 'payment_query';
}
// Status query
else if (text.match(/status|where|delivery|wapi|hali/i)) {
  messageType = 'status_query';
}
// Support
else if (text.match(/help|support|saaidie|msaada|assist/i)) {
  messageType = 'support';
}

return { message_type: messageType, ...$input.item.json };

// Determine user type and conversation window
// Architecture: See docs/WAAS_ARCHITECTURE.md (Layer 2: Orchestration)

const buyerResult = $('Check Buyer').first()?.json || [];
const sellerResult = $('Check Seller').first()?.json || [];
const messageData = $input.item.json;

let userType = 'new_user';
if (sellerResult.length > 0) {
  userType = 'seller';
} else if (buyerResult.length > 0) {
  userType = 'buyer';
}

// Check conversation window (24h from last message)
// For now, assume within window (will be checked in send_whatsapp workflow)
const sessionAllowed = true; // TODO: Query last_message_at from database

// Determine priority
let priority = 'low';
if (['order', 'payment_query'].includes(messageData.message_type)) {
  priority = 'high';
} else if (['status_query', 'support'].includes(messageData.message_type)) {
  priority = 'medium';
}

// Determine fallback allowed
const fallbackAllowed = ['order', 'payment_query', 'status_query'].includes(messageData.message_type);

return {
  ...messageData,
  user_type: userType,
  priority: priority,
  session_allowed: sessionAllowed,
  fallback_allowed: fallbackAllowed,
  phone: messageData.from
};
